// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        vm.assume(caddress != address(0));
        vm.assume(from != address(0));
        // We need caddress to be a contract that implements transferFrom to avoid revert
        // Deploy a helper that always succeeds on transferFrom
        Helper h = new Helper();
        caddress = address(h);
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, caddress, _tos, v));
        assertTrue(ok && abi.decode(ret, (bool)));
    }
}

contract Helper {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
